      mark.style.top = `${i2 / Math.max(1, lines.length) * 100}%`;
      mark.title = t(`\u041F\u0435\u0440\u0435\u0439\u0442\u0438 \u043A \u0441\u0442\u0440\u043E\u043A\u0435 ${i2 + 1}`);
